package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;

/** Explicit table-pair meaning and protected endpoints; relationship links never grant access. */
final class TypedRelationships {
 private TypedRelationships() {}
 static Map<String,Object> type(Store.Db db,String id)throws SQLException{var row=db.one("SELECT * FROM os_relation_type WHERE type_id=?",id);if(row==null)throw new Failure(404,"Relationship type not found");return row;}
 static String direction(Object input){require(input instanceof String && Set.of("outbound","inbound").contains(input),"Choose outbound or inbound direction");return input.toString();}
 static Map<String,Object> adminPage(Store.Db db,String id)throws SQLException{Service.requireAccountAdministrator(db,db.viewerId);return map("types",db.all("SELECT * FROM os_relation_type ORDER BY forward_label,type_id"),"type",id.isEmpty()?map("type_id","","source_table","cmdb_ci","target_table","cmdb_ci","forward_label","","inverse_label","","propagates",0,"active",0,"revision",0):type(db,id),"tables",db.all("SELECT name FROM os_schema ORDER BY name"));}
 static Map<String,Object> configure(Store.Db db,String id,Object input)throws Exception {
  Service.requireAccountAdministrator(db,db.viewerId);if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var body=object(input);require(body.keySet().equals(Set.of("revision","source_table","target_table","forward_label","inverse_label","propagates","active")),"Provide the reviewed relationship type only");var old=id.isEmpty()?map("revision",0):type(db,id);ProblemInvestigations.revision(body.get("revision"),old.get("revision"));String source=WorkJobs.text(body.get("source_table"),80),target=WorkJobs.text(body.get("target_table"),80),forward=WorkJobs.text(body.get("forward_label"),80),inverse=WorkJobs.text(body.get("inverse_label"),80);Service.schema(db,source);Service.schema(db,target);require(body.get("propagates") instanceof Boolean && body.get("active") instanceof Boolean,"Choose availability and impact explicitly");boolean propagates=(Boolean)body.get("propagates");require(!propagates || source.equals("cmdb_ci") && target.equals("cmdb_ci"),"Only CI-to-CI relationships propagate dependency impact");int impact=propagates?1:0;var semantic=map("source_table",source,"target_table",target,"forward_label",forward,"inverse_label",inverse,"propagates",impact);if(!id.isEmpty() && db.count("SELECT COUNT(*) FROM os_typed_relation WHERE type_id=?",id)>0)for(var field:semantic.entrySet())if(!field.getValue().equals(old.get(field.getKey())))throw new Failure(409,"A used relationship type retains its meaning; define a new type");require(db.count("SELECT COUNT(*) FROM os_relation_type WHERE source_table=? AND target_table=? AND forward_label=? AND inverse_label=? AND type_id<>?",source,target,forward,inverse,id)==0,"This relationship meaning already exists");if(id.isEmpty()){require(db.count("SELECT COUNT(*) FROM os_relation_type")<100,"At most 100 relationship types are supported");id=Values.id();}db.update("INSERT INTO os_relation_type(type_id,source_table,target_table,forward_label,inverse_label,propagates,active,revision) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(type_id) DO UPDATE SET source_table=excluded.source_table,target_table=excluded.target_table,forward_label=excluded.forward_label,inverse_label=excluded.inverse_label,propagates=excluded.propagates,active=excluded.active,revision=excluded.revision",id,source,target,forward,inverse,impact,(Boolean)body.get("active")?1:0,((Number)old.get("revision")).intValue()+1);SecurityEvents.record(db,db.viewerId,db.viewerId,"relationship.type_configured",map("type_id",id));return adminPage(db,id);
 }
 static Map<String,Object> page(Store.Db db,String table,String id)throws SQLException {
  var record=Service.readRecord(db,table,id);var params=new ArrayList<Object>(List.of(id,id));String access=RecordAccess.filter(db,"s.sys_id",params)+" AND "+RecordAccess.filter(db,"t.sys_id",params);var links=new ArrayList<Map<String,Object>>();boolean truncated=false;for(var row:db.all("SELECT e.*,k.source_table,k.target_table,k.forward_label,k.inverse_label,k.propagates FROM os_typed_relation e JOIN os_relation_type k ON k.type_id=e.type_id JOIN os_record s ON s.sys_id=e.source_id JOIN os_record t ON t.sys_id=e.target_id WHERE (e.source_id=? OR e.target_id=?) AND "+access+" ORDER BY e.updated DESC,e.relation_id",params.toArray())){boolean outbound=row.get("source_id").equals(id);String relatedTable=row.get(outbound?"target_table":"source_table").toString();if(!RecordPolicy.allows(Service.schema(db,relatedTable),"read",db.viewerRole))continue;if(links.size()==100){truncated=true;break;}var related=Service.readRecord(db,relatedTable,row.get(outbound?"target_id":"source_id").toString());row.put("direction",outbound?"outbound":"inbound");row.put("label",row.get(outbound?"forward_label":"inverse_label"));row.put("related_table",relatedTable);row.put("related",FieldAccess.serialize(db,related));row.put("history",db.all("SELECT revision,detail FROM os_relation_history WHERE relation_id=? ORDER BY revision DESC LIMIT 100",row.get("relation_id")));links.add(row);}var types=new ArrayList<Map<String,Object>>();if("admin".equals(db.viewerRole))for(var kind:db.all("SELECT * FROM os_relation_type WHERE active=1 AND (source_table=? OR target_table=?) ORDER BY forward_label,type_id",table,table))types.add(kind);return map("record",FieldAccess.serialize(db,record),"table",table,"links",links,"truncated",truncated,"types",types,"can_edit","admin".equals(db.viewerRole));
 }
 static Map<String,Object> endpoints(Store.Db db,String table,String id,String typeId,String direction,String relatedId)throws SQLException {
  Service.requireAccountAdministrator(db,db.viewerId);var kind=type(db,typeId);boolean outbound=direction(direction).equals("outbound");require(kind.get(outbound?"source_table":"target_table").equals(table),"Relationship direction does not accept this table");require(!id.equals(relatedId),"A record cannot have a typed relationship to itself");var record=Service.record(db,table,id);String otherTable=kind.get(outbound?"target_table":"source_table").toString();var related=Service.record(db,otherTable,relatedId);RecordPolicy.require(Service.schema(db,table),"update",db.viewerRole);RecordPolicy.require(Service.schema(db,otherTable),"update",db.viewerRole);String source=outbound?id:relatedId,target=outbound?relatedId:id;var edge=db.one("SELECT * FROM os_typed_relation WHERE type_id=? AND source_id=? AND target_id=?",typeId,source,target);return map("type",kind,"record",record,"related",related,"related_table",otherTable,"source_id",source,"target_id",target,"edge",edge==null?map("revision",0,"active",0):edge);
 }
 static Map<String,Object> choose(Store.Db db,String table,String id,Map<String,String> input)throws SQLException {
  Service.requireAccountAdministrator(db,db.viewerId);Service.readRecord(db,table,id);var args=new LinkedHashMap<>(input);String typeId=Objects.toString(args.remove("type_id"),""),direction=direction(args.remove("direction"));var kind=type(db,typeId);boolean outbound=direction.equals("outbound");require(kind.get(outbound?"source_table":"target_table").equals(table),"Relationship direction does not accept this table");if(((Number)kind.get("active")).intValue()!=1)throw new Failure(409,"Relationship type is inactive");String relatedTable=kind.get(outbound?"target_table":"source_table").toString();var result=ReferenceSearch.search(db,relatedTable,args);result.putAll(map("type",kind,"direction",direction,"record_id",id,"table",table,"query",args.getOrDefault("q","")));return result;
 }
 static Map<String,Object> review(Store.Db db,String table,String id,Map<String,String> args)throws SQLException {
  require(args.keySet().equals(Set.of("type_id","direction","related_id")),"Select one type, direction and related record");var endpoints=endpoints(db,table,id,args.get("type_id"),args.get("direction"),args.get("related_id"));var kind=object(endpoints.get("type"));var edge=object(endpoints.get("edge"));var command=map("type_id",args.get("type_id"),"direction",args.get("direction"),"related_id",args.get("related_id"),"type_revision",kind.get("revision"),"record_revision",object(endpoints.get("record")).get("revision"),"related_revision",object(endpoints.get("related")).get("revision"),"revision",edge.get("revision"),"remove",((Number)edge.get("active")).intValue()==1);endpoints.put("record",FieldAccess.serialize(db,object(endpoints.get("record"))));endpoints.put("related",FieldAccess.serialize(db,object(endpoints.get("related"))));endpoints.put("command",command);return endpoints;
 }
 static Map<String,Object> change(Store.Db db,String table,String id,Object input)throws Exception {
  Service.requireAccountAdministrator(db,db.viewerId);if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var body=object(input);require(body.keySet().equals(Set.of("type_id","direction","related_id","type_revision","record_revision","related_revision","revision","remove","reason")),"Apply the reviewed relationship change only");require(body.get("remove") instanceof Boolean,"Choose add or remove explicitly");String reason=WorkJobs.text(body.get("reason"),2000);var ends=endpoints(db,table,id,WorkJobs.text(body.get("type_id"),32),direction(body.get("direction")),WorkJobs.text(body.get("related_id"),32));var kind=object(ends.get("type"));var record=object(ends.get("record"));var related=object(ends.get("related"));var edge=object(ends.get("edge"));for(var revision:List.of(new Object[]{"type_revision",kind.get("revision")},new Object[]{"record_revision",record.get("revision")},new Object[]{"related_revision",related.get("revision")},new Object[]{"revision",edge.get("revision")}))ProblemInvestigations.revision(body.get(revision[0]),revision[1]);boolean remove=(Boolean)body.get("remove");if(!remove && ((Number)kind.get("active")).intValue()!=1)throw new Failure(409,"Relationship type is inactive");require(remove==(((Number)edge.get("active")).intValue()==1),"The requested link state is already current");String relationId=edge.containsKey("relation_id")?edge.get("relation_id").toString():Values.id();if(!edge.containsKey("relation_id"))for(Object endpoint:List.of(ends.get("source_id"),ends.get("target_id")))require(db.count("SELECT COUNT(*) FROM os_typed_relation WHERE source_id=? OR target_id=?",endpoint,endpoint)<1000,"This record has reached retained relationship capacity");int revision=((Number)edge.get("revision")).intValue()+1;String actor=Service.account(db,db.viewerId).get("name").toString(),created=now();var detail=map("actor",actor,"actor_id",db.viewerId,"reason",reason,"remove",remove,"created",created,"type_revision",kind.get("revision"),"source_revision",body.get("direction").equals("outbound")?record.get("revision"):related.get("revision"),"target_revision",body.get("direction").equals("outbound")?related.get("revision"):record.get("revision"));db.update("INSERT INTO os_typed_relation(relation_id,type_id,source_id,target_id,active,revision,updated) VALUES(?,?,?,?,?,?,?) ON CONFLICT(relation_id) DO UPDATE SET active=excluded.active,revision=excluded.revision,updated=excluded.updated",relationId,kind.get("type_id"),ends.get("source_id"),ends.get("target_id"),remove?0:1,revision,created);db.update("INSERT INTO os_relation_history(relation_id,revision,detail) VALUES(?,?,?)",relationId,revision,JSON.writeValueAsString(detail));for(var item:List.of(record,related))Service.audit(db,item,actor,"relationship.changed",map("relation_id",relationId,"type_id",kind.get("type_id"),"revision",revision,"remove",remove,"reason",reason));return page(db,table,id);
 }
 static void deleting(Store.Db db,String id)throws SQLException{if(db.count("SELECT COUNT(*) FROM os_typed_relation WHERE active=1 AND (source_id=? OR target_id=?)",id,id)>0)throw new Failure(409,"Remove active typed relationships before deleting this record");}
}
